input.command:
cd /Users/guygouri/Devlab/ernlang/ern/formal && f=Ern/MemoryModel/RefinementArena.lean && python3 - "$f" <<'EOF'
import sys,re
p=sys.argv[1]; lines=open(p).read().split('\n')
for i,l in enumerate(lines):
    if len(l)>100: print("LONG",i+1,len(l))
# top-level decls
src=open(p).read()
for m in re.finditer(r'(/--(?:(?!-/).)*?-/\s*)?\n((?:private |protected )?(?:theorem|def|inductive|structure|instance|abbrev)\s+(\S+))', src, re.S):
    doc=m.group(1); name=m.group(3)
    if not doc: print("NODOC", name)
    elif '§' not in doc and 'Part' not in doc: print("NOSEC", name)
    elif '§' not in doc: print("PARTONLY", name)
EOF
grep -nE "\b(sorry|admit|native_decide|noncomputable|set_option)\b|^\s*axiom\b|MM-0|K[1-5]\b|L[1-8]\b" $f | head

